CREATE OR REPLACE FUNCTION public.record_transfer_recovery(p_order uuid, p_worker text, p_key text, p_detail text, p_amount integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result uuid;
begin
  if p_order is null
     or p_worker is null
     or p_key is null
     or p_detail is null
     or length(p_key) < 3
     or length(p_key) > 250 then
    raise exception 'Invalid transfer recovery identity';
  end if;

  -- Take the parent lock first, matching refund settlement and transfer
  -- completion. A stale owner returns null without changing state or audit.
  perform 1 from public.orders where id = p_order for key share;
  if not found then return null; end if;

  update public.transfer_intents
  set status = 'failed',
      attempts = greatest(attempts, 8),
      next_attempt_at = null,
      last_error = left(p_detail, 500),
      locked_at = null,
      locked_by = null,
      lease_expires_at = null,
      updated_at = now()
  where order_id = p_order
    and status = 'processing'
    and locked_by = p_worker
    and lease_expires_at > now()
    and transfer_reference is null;
  if not found then return null; end if;

  insert into public.payment_recoveries (
    order_id, kind, recovery_key, amount_cents, detail
  ) values (
    p_order,
    'transfer_unresolved',
    p_key,
    p_amount,
    left(p_detail, 1000)
  )
  on conflict (recovery_key) do update
  set last_seen_at = now(),
      detail = excluded.detail,
      amount_cents = excluded.amount_cents,
      status = 'open',
      resolved_by = null,
      resolved_at = null,
      resolution_note = null
  returning id into v_result;

  return v_result;
end;
$function$;

